class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        def solve():
            tok = tokens.pop()
            if tok not in ("+", "-", "*", "/"):
                return int(tok)
            b = solve()
            a = solve()
            if tok == "+":
                return a + b
            if tok == "-":
                return a - b
            if tok == "*":
                return a * b
            return int(a / b)
        return solve()

class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        stack = []
        for tok in tokens:
            if tok in ("+", "-", "*", "/"):
                b = stack.pop()
                a = stack.pop()
                if tok == "+":
                    stack.append(a + b)
                elif tok == "-":
                    stack.append(a - b)
                elif tok == "*":
                    stack.append(a * b)
                else:
                    stack.append(int(a / b))
            else:
                stack.append(int(tok))
        return stack[0]
